mapper.select:
SELECT a.article_id, a.title, a.summary, a.category_id, a.cover_image, a.view_count, a.like_count, a.author_id, a.author_name, a.status, a.create_time, a.update_time, a.publish_time, c.category_name FROM my_article a LEFT JOIN article_category c ON a.category_id = c.category_id
AND a.status = #{params.status}
AND (a.title LIKE CONCAT('%', #{params.keyword}, '%') OR a.summary LIKE CONCAT('%', #{params.keyword}, '%'))
AND a.category_id = #{params.categoryId}
AND a.author_id = #{params.authorId}
ORDER BY a.create_time DESC

SELECT * FROM my_article
WHERE author_id = #{authorId}

    AND status = #{params.status}

ORDER BY create_time DESC

mapper.insert:
INSERT INTO article_view_record (article_id, user_id, view_time, ip_address)
VALUES (#{articleId}, #{userId}, NOW(), #{ipAddress})
ON DUPLICATE KEY UPDATE view_time = NOW(), ip_address = #{ipAddress}

mapper.select:
SELECT a.*, c.category_name, u.nick_name as author_name FROM my_article a LEFT JOIN article_category c ON a.category_id = c.category_id LEFT JOIN my_user u ON a.author_id = u.user_id
AND (a.title LIKE CONCAT('%', #{params.keyword}, '%') OR a.summary LIKE CONCAT('%', #{params.keyword}, '%'))
AND a.category_id = #{params.categoryId}
AND a.status = #{params.status}
ORDER BY a.create_time DESC

mapper.update:
UPDATE my_article
SET status = #{status}, update_time = NOW()
WHERE article_id = #{articleId}
